// The decision is made here, not by the model: it is handed a verdict and the exact slots that were saved for propose_booking.
const s = $('Settings').first().json.fields;
const inp = $('Trigger').first().json;
const services = $('Services').all().map(i => i.json.fields || {}).filter(x => x.service_id);
const svc = services.find(x => x.service_id === String(inp.service_id || '').trim().toLowerCase());
const iso = (t) => t.toISO({ suppressMilliseconds: true });
if (!svc) return [{ json: { verdict: 'UNKNOWN_SERVICE ' + services.map(x => `${x.service_id} (${x.name}, ${x.duration_min} min)`).join('; '), offered_json: '[]', offered_at: DateTime.utc().toISO() } }];
const tz = s.timezone, hours = JSON.parse(s.working_hours);
const step = Number(s.slot_step_min), lead = Number(s.min_lead_min), dur = Number(svc.duration_min);
// FreeBusy Booked Slots: items {start, end}; the empty {} item of alwaysOutputData is dropped here.
const busy = $('FreeBusy').all().map(i => i.json).filter(b => b.start && b.end).map(b => ({ s: DateTime.fromISO(b.start), e: DateTime.fromISO(b.end) }));
const now = DateTime.now().setZone(tz);
const day0 = DateTime.fromISO(String(inp.date || '').trim(), { zone: tz }).startOf('day');
if (!day0.isValid) return [{ json: { verdict: 'NONE invalid date, expected YYYY-MM-DD', offered_json: '[]', offered_at: DateTime.utc().toISO() } }];
const pod = String(inp.part_of_day || '').toLowerCase();
// morning: the visit must END by noon (a 60 min visit may start at 11:00 but not at 11:30); afternoon and evening are decided by the start.
const inPart = (t) => !pod || (pod === 'morning' && t.hour < 12 && t.plus({ minutes: dur }) <= t.set({ hour: 12, minute: 0 })) || (pod === 'afternoon' && t.hour >= 12 && t.hour < 17) || (pod === 'evening' && t.hour >= 17);
const dayKey = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
function slots(day) {
  const wh = hours[dayKey[day.weekday % 7]];
  if (!wh) return [];
  const [oh, om] = wh[0].split(':').map(Number), [ch, cm] = wh[1].split(':').map(Number);
  let t = day.set({ hour: oh, minute: om });
  const close = day.set({ hour: ch, minute: cm });
  const out = [];
  while (t.plus({ minutes: dur }) <= close) {
    const end = t.plus({ minutes: dur });
    const clash = busy.some(b => b.s < end && b.e > t);
    if (!clash && t >= now.plus({ minutes: lead })) out.push(t);
    t = t.plus({ minutes: step });
  }
  return out;
}
const today = slots(day0).filter(inPart).slice(0, 6);
let offered, verdict;
if (today.length) { offered = today; verdict = 'FREE ' + offered.map(iso).join(', '); }
else {
  offered = [];
  for (let d = 1; d <= 7 && offered.length < 3; d++) { const l = slots(day0.plus({ days: d })).filter(inPart); if (l.length) offered.push(l[0]); }
  verdict = 'NONE ' + (offered.length ? 'nearest: ' + offered.map(iso).join(', ') : 'no slots in the next 7 days');
}
return [{ json: { verdict, offered_json: JSON.stringify(offered.map(iso)), offered_at: DateTime.utc().toISO() } }];

// Validate first: an empty or malformed contact_id must match NO client row (a comparison with '' would match every row whose column is blank).
const raw = String($('Trigger').first().json.contact_id || '').trim();
const ok = /^(tg:\d{1,20}|wa:\+\d{1,20})$/.test(raw);
const formula = ok
  ? (raw.startsWith('tg:') ? "{telegram_chat_id}='" + raw.slice(3) + "'" : "{phone}='" + raw.slice(3) + "'")
  : "{client_id}='__no_such_client__'";
return [{ json: { formula } }];
